function [a, comp] = erp_simple(r_sat, r_sun, cr_aom, doy)
%ERP_SIMPLE  erp.simple(rSat, rSun, CrAoM, doy): the whole visible Earth as one radial source, Knocke's zonal at the equator.
%   r_sat: real[1][3] (passed a plain number)
%   r_sun: real[1][3] (passed a plain number)
%   cr_aom: real[1] (passed a plain number)
%   doy: real[1] (passed a plain number)
%   returns a: real[1][3] (passed a plain number)
%   returns comp: ErpComp (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    a = zeros(3, 1);
    comp = asils.models.erp.ErpComp_zero();
    k = asils.models.de440.de440_constants();
    d = asils.pc.norm_(r_sat);
    zhat = [(r_sat(1) / d); (r_sat(2) / d); (r_sat(3) / d)];
    [alb, emi] = asils.models.erp.zonal_coeffs(0, doy);
    q = (k.re_earth / d);
    f = (q * q);
    ns = asils.pc.norm_(r_sun);
    c0 = asils.pc.dot_(zhat, [(r_sun(1) / ns); (r_sun(2) / ns); (r_sun(3) / ns)]);
    cz = asils.pc.choose((c0 > 0), c0, 0);
    esw = (((alb * k.tsi) * cz) * f);
    elw = ((emi * (k.tsi / 4)) * f);
    ks = ((cr_aom / k.c) * esw);
    kl = ((cr_aom / k.c) * elw);
    comp = asils.models.erp.ErpComp_zero();
    comp.sw = [(ks * zhat(1)); (ks * zhat(2)); (ks * zhat(3))];
    comp.lw = [(kl * zhat(1)); (kl * zhat(2)); (kl * zhat(3))];
    a = [(comp.sw(1) + comp.lw(1)); (comp.sw(2) + comp.lw(2)); (comp.sw(3) + comp.lw(3))];
end
